<script setup lang="ts">import {computed} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import GraphView from '../components/GraphView.vue';import PhaseCompare from '../components/PhaseCompare.vue';import ShortestPanel from '../components/ShortestPanel.vue';const props=defineProps<{data:Workspace}>();const emit=defineEmits<{go:[string]}>();const run=computed(()=>props.data.runs.find(r=>r.status==='completed'));</script><template><PageHeading code="01 / RESILIENCE ATLAS" title="流量与绕行，都从一份网络出发。" description="衡远联运规划组 · 18人。模拟边容量箱/小时，时长分钟；两组结果用同一边快照。"/><PhaseCompare v-if="run" :result="run.result"/><div class="overview-intro"><div><span class="eyebrow">CURRENT OUTAGE SCENARIO</span><h2>{{data.scenarios.find(s=>s.id===run?.scenario_id)?.name||'暂无推演'}}</h2><p>逐边独立残量、节点守恒和最大流=最小割证据可复核。</p></div><button class="secondary" @click="emit('go','results')">展开流量与绕行　↗</button></div><section class="paper" v-if="run"><div class="section-heading"><h2>停用后 · 最大流与残量割</h2><span>{{run.result.source}} → {{run.result.sink}} / {{run.result.arcs.length}}条独立边</span></div><GraphView :nodes="run.result.nodes" :arcs="run.result.arcs" :flow="run.result.outage.max_flow" :path="run.result.outage.shortest" :disabled="run.result.disabled_arc_ids" mode="flow" id-prefix="overview"/></section><ShortestPanel v-if="run" :path="run.result.outage.shortest"/></template>
